-- =====================================================================
-- Pizzaria Santoluppo — Script SQL completo (MySQL 8.0)
-- Entrega 2 — Modelagem de Banco de Dados
--
-- Como executar: abrir este arquivo no MySQL Workbench e executar tudo
-- (raio sem cursor / Ctrl+Shift+Enter). O script apaga e recria o banco
-- SANTOLUPPO, então pode ser executado quantas vezes for preciso.
--
-- Ordem: 1 CREATE DATABASE · 2 CREATE TABLE · 3 constraints ·
--        4 INSERT (massa de dados) · 5 SELECT com JOIN · 6 UPDATE ·
--        7 DELETE · 8 consultas gerenciais · 9 consultas de auditoria
-- =====================================================================


-- =====================================================================
-- 1. CREATE DATABASE
-- =====================================================================
DROP DATABASE IF EXISTS SANTOLUPPO;
CREATE DATABASE SANTOLUPPO
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_0900_ai_ci;
USE SANTOLUPPO;


-- =====================================================================
-- 2 e 3. CREATE TABLE com as constraints
-- As tabelas são criadas na ordem das dependências: primeiro as que não
-- têm chave estrangeira, depois as que apontam para elas.
-- Todas as FKs usam ON DELETE RESTRICT (padrão): nada que já foi usado
-- em pedido pode ser apagado, o que preserva o histórico (RN05).
-- =====================================================================

-- ---------------------------------------------------------------------
-- CLIENTE — o telefone é a chave de busca no atendimento (RN09)
-- ---------------------------------------------------------------------
CREATE TABLE CLIENTE (
    ID_CLIENTE   INT          NOT NULL AUTO_INCREMENT,
    NM_CLIENTE   VARCHAR(120) NOT NULL,
    DS_TELEFONE  VARCHAR(15)  NOT NULL,
    CONSTRAINT PK_CLIENTE PRIMARY KEY (ID_CLIENTE),
    CONSTRAINT UQ_CLIENTE_TELEFONE UNIQUE (DS_TELEFONE)              -- RN09
) ENGINE = InnoDB;

-- ---------------------------------------------------------------------
-- ENDERECO — histórico de endereços do cliente (P1, RN10)
-- ---------------------------------------------------------------------
CREATE TABLE ENDERECO (
    ID_ENDERECO    INT          NOT NULL AUTO_INCREMENT,
    ID_CLIENTE     INT          NOT NULL,
    DS_RUA         VARCHAR(150) NOT NULL,
    NR_RESIDENCIA  VARCHAR(20)  NOT NULL,
    NM_BAIRRO      VARCHAR(80)  NOT NULL,
    CD_CEP         VARCHAR(8)   NULL,
    IN_ATIVO       BOOLEAN      NOT NULL DEFAULT TRUE,                 -- RN10
    DT_CADASTRO    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT PK_ENDERECO PRIMARY KEY (ID_ENDERECO),
    -- par (endereço, cliente) único: alvo da FK composta de PEDIDO (RN16)
    CONSTRAINT UQ_ENDERECO_CLIENTE UNIQUE (ID_ENDERECO, ID_CLIENTE),
    CONSTRAINT FK_ENDERECO_CLIENTE FOREIGN KEY (ID_CLIENTE)
        REFERENCES CLIENTE (ID_CLIENTE),
    CONSTRAINT CK_ENDERECO_CEP CHECK (CD_CEP IS NULL OR CD_CEP REGEXP '^[0-9]{8}$')
) ENGINE = InnoDB;

-- ---------------------------------------------------------------------
-- PRODUTO — cardápio único; o código é o número decorado (RN01)
-- ---------------------------------------------------------------------
CREATE TABLE PRODUTO (
    CD_PRODUTO     INT           NOT NULL,                             -- sem AUTO_INCREMENT: 58 é sempre a mussarela
    NM_SABOR       VARCHAR(100)  NOT NULL,
    TP_CATEGORIA   VARCHAR(20)   NOT NULL,
    DS_TAMANHO     VARCHAR(15)   NULL,
    VL_PRECO       DECIMAL(10,2) NOT NULL,
    IN_DISPONIVEL  BOOLEAN       NOT NULL DEFAULT TRUE,                -- RN04
    CONSTRAINT PK_PRODUTO PRIMARY KEY (CD_PRODUTO),
    CONSTRAINT UQ_PRODUTO_NOME UNIQUE (NM_SABOR, TP_CATEGORIA),
    CONSTRAINT CK_PRODUTO_CATEGORIA CHECK (TP_CATEGORIA IN ('PIZZA', 'BROTO', 'BEBIDA', 'REFRIGERANTE')),
    CONSTRAINT CK_PRODUTO_PRECO CHECK (VL_PRECO > 0),
    -- tamanho só existe para pizza e broto
    CONSTRAINT CK_PRODUTO_TAMANHO CHECK (
        (TP_CATEGORIA IN ('PIZZA', 'BROTO') AND DS_TAMANHO IS NOT NULL)
     OR (TP_CATEGORIA IN ('BEBIDA', 'REFRIGERANTE') AND DS_TAMANHO IS NULL))
) ENGINE = InnoDB;

-- ---------------------------------------------------------------------
-- FORMAS_PAGAMENTOS — domínio fechado: Dinheiro, PIX, Cartão (RN03)
-- ---------------------------------------------------------------------
CREATE TABLE FORMAS_PAGAMENTOS (
    ID_FORMA   INT         NOT NULL AUTO_INCREMENT,
    DS_METODO  VARCHAR(30) NOT NULL,
    CONSTRAINT PK_FORMAS_PAGAMENTOS PRIMARY KEY (ID_FORMA),
    CONSTRAINT UQ_FORMAS_METODO UNIQUE (DS_METODO)
) ENGINE = InnoDB;

-- ---------------------------------------------------------------------
-- FORNECEDOR (P5, RN11)
-- ---------------------------------------------------------------------
CREATE TABLE FORNECEDOR (
    ID_FORNECEDOR        INT          NOT NULL AUTO_INCREMENT,
    NM_FORNECEDOR        VARCHAR(100) NOT NULL,
    TP_FORNECIMENTO      VARCHAR(30)  NOT NULL,
    DS_TELEFONE          VARCHAR(15)  NOT NULL,                        -- RN11
    IN_ENVIA_MERCADORIA  BOOLEAN      NOT NULL DEFAULT FALSE,
    CONSTRAINT PK_FORNECEDOR PRIMARY KEY (ID_FORNECEDOR),
    CONSTRAINT CK_FORNECEDOR_TIPO CHECK (TP_FORNECIMENTO IN ('EMBALAGENS', 'BEBIDAS', 'MERCADORIA GERAL'))
) ENGINE = InnoDB;

-- ---------------------------------------------------------------------
-- INSUMO — só disponibilidade, sem quantidade em estoque (RN04)
-- ---------------------------------------------------------------------
CREATE TABLE INSUMO (
    ID_INSUMO      INT          NOT NULL AUTO_INCREMENT,
    ID_FORNECEDOR  INT          NULL,                                  -- insumo comprado pelo dono no mercado não tem fornecedor
    NM_INSUMO      VARCHAR(100) NOT NULL,
    TP_INSUMO      VARCHAR(30)  NOT NULL,
    IN_DISPONIVEL  BOOLEAN      NOT NULL DEFAULT TRUE,
    CONSTRAINT PK_INSUMO PRIMARY KEY (ID_INSUMO),
    CONSTRAINT UQ_INSUMO_NOME UNIQUE (NM_INSUMO),
    CONSTRAINT FK_INSUMO_FORNECEDOR FOREIGN KEY (ID_FORNECEDOR)
        REFERENCES FORNECEDOR (ID_FORNECEDOR),
    CONSTRAINT CK_INSUMO_TIPO CHECK (TP_INSUMO IN ('INGREDIENTE', 'EMBALAGEM', 'BEBIDA'))
) ENGINE = InnoDB;

-- ---------------------------------------------------------------------
-- PRODUTO_INSUMO — relacionamento N:N "Compõe"
-- ---------------------------------------------------------------------
CREATE TABLE PRODUTO_INSUMO (
    CD_PRODUTO  INT NOT NULL,
    ID_INSUMO   INT NOT NULL,
    CONSTRAINT PK_PRODUTO_INSUMO PRIMARY KEY (CD_PRODUTO, ID_INSUMO),
    CONSTRAINT FK_PRODINS_PRODUTO FOREIGN KEY (CD_PRODUTO) REFERENCES PRODUTO (CD_PRODUTO),
    CONSTRAINT FK_PRODINS_INSUMO  FOREIGN KEY (ID_INSUMO)  REFERENCES INSUMO (ID_INSUMO)
) ENGINE = InnoDB;

-- ---------------------------------------------------------------------
-- PEDIDO — núcleo transacional
-- ---------------------------------------------------------------------
CREATE TABLE PEDIDO (
    ID_PEDIDO             INT           NOT NULL AUTO_INCREMENT,
    ID_CLIENTE            INT           NOT NULL,
    ID_ENDERECO           INT           NULL,                          -- nulo na retirada
    DT_HORA               DATETIME      NOT NULL,
    TP_PEDIDO             VARCHAR(15)   NOT NULL,
    DS_STATUS_ENTREGA     VARCHAR(30)   NOT NULL DEFAULT 'EM PREPARO',
    IN_ENTREGA_FRUSTRADA  BOOLEAN       NOT NULL DEFAULT FALSE,        -- RN10 / P1
    QT_DISTANCIA_KM       DECIMAL(5,2)  NULL,
    VL_TAXA_ENTREGA       DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    DS_CANCELAMENTO       TEXT          NULL,                          -- motivo (RN02)
    CONSTRAINT PK_PEDIDO PRIMARY KEY (ID_PEDIDO),
    CONSTRAINT FK_PEDIDO_CLIENTE FOREIGN KEY (ID_CLIENTE)
        REFERENCES CLIENTE (ID_CLIENTE),
    -- FK composta: o endereço do pedido tem de ser do próprio cliente (RN16)
    CONSTRAINT FK_PEDIDO_ENDERECO FOREIGN KEY (ID_ENDERECO, ID_CLIENTE)
        REFERENCES ENDERECO (ID_ENDERECO, ID_CLIENTE),
    CONSTRAINT CK_PEDIDO_TIPO CHECK (TP_PEDIDO IN ('ENTREGA', 'RETIRADA')),
    CONSTRAINT CK_PEDIDO_STATUS CHECK (DS_STATUS_ENTREGA IN
        ('EM PREPARO', 'SAIU PARA ENTREGA', 'ENTREGUE', 'RETIRADO', 'CANCELADO')),
    -- status coerente com o tipo do pedido
    CONSTRAINT CK_PEDIDO_STATUS_TIPO CHECK (
        (TP_PEDIDO = 'ENTREGA'  AND DS_STATUS_ENTREGA <> 'RETIRADO')
     OR (TP_PEDIDO = 'RETIRADA' AND DS_STATUS_ENTREGA NOT IN ('SAIU PARA ENTREGA', 'ENTREGUE'))),
    -- RN15: entrega exige endereço e distância; retirada não tem endereço nem taxa
    CONSTRAINT CK_PEDIDO_ENDERECO CHECK (
        (TP_PEDIDO = 'ENTREGA'  AND ID_ENDERECO IS NOT NULL AND QT_DISTANCIA_KM IS NOT NULL)
     OR (TP_PEDIDO = 'RETIRADA' AND ID_ENDERECO IS NULL AND QT_DISTANCIA_KM IS NULL AND VL_TAXA_ENTREGA = 0)),
    -- RN12 e RN19: até 3 km grátis; acima de 3 km R$ 5,00; não entrega acima de 8 km
    CONSTRAINT CK_PEDIDO_TAXA CHECK (
        QT_DISTANCIA_KM IS NULL
     OR (QT_DISTANCIA_KM > 0 AND QT_DISTANCIA_KM <= 3 AND VL_TAXA_ENTREGA = 0.00)
     OR (QT_DISTANCIA_KM > 3 AND QT_DISTANCIA_KM <= 8 AND VL_TAXA_ENTREGA = 5.00)),
    -- RN14: terça a quinta e domingo das 18h às 23h; sexta e sábado das 18h à 00h; fechado na segunda
    -- DAYOFWEEK: 1 = domingo, 2 = segunda, ..., 6 = sexta, 7 = sábado
    CONSTRAINT CK_PEDIDO_HORARIO CHECK (
        (DAYOFWEEK(DT_HORA) IN (1, 3, 4, 5) AND HOUR(DT_HORA) BETWEEN 18 AND 22)
     OR (DAYOFWEEK(DT_HORA) IN (6, 7)       AND HOUR(DT_HORA) BETWEEN 18 AND 23)),
    -- RN02 e RN05: cancelado se e somente se houver motivo
    CONSTRAINT CK_PEDIDO_CANCELAMENTO CHECK (
        (DS_STATUS_ENTREGA = 'CANCELADO'  AND DS_CANCELAMENTO IS NOT NULL AND DS_CANCELAMENTO <> '')
     OR (DS_STATUS_ENTREGA <> 'CANCELADO' AND DS_CANCELAMENTO IS NULL)),
    -- entrega frustrada só existe em pedido de entrega
    CONSTRAINT CK_PEDIDO_FRUSTRADA CHECK (IN_ENTREGA_FRUSTRADA = FALSE OR TP_PEDIDO = 'ENTREGA')
) ENGINE = InnoDB;

CREATE INDEX IX_PEDIDO_DATA ON PEDIDO (DT_HORA);                     -- fechamento de caixa por dia (P3)

-- ---------------------------------------------------------------------
-- ITEM_PEDIDO — entidade associativa "Contém" + segundo sabor
-- ---------------------------------------------------------------------
CREATE TABLE ITEM_PEDIDO (
    ID_PEDIDO      INT           NOT NULL,
    NR_ITEM        INT           NOT NULL,
    CD_PRODUTO     INT           NOT NULL,
    CD_PRODUTO_2   INT           NULL,                                 -- segundo sabor (meio a meio)
    QT_ITEM        INT           NOT NULL DEFAULT 1,
    VL_UNITARIO    DECIMAL(10,2) NOT NULL,                             -- preço cobrado na venda
    DS_OBSERVACAO  VARCHAR(255)  NULL,
    CONSTRAINT PK_ITEM_PEDIDO PRIMARY KEY (ID_PEDIDO, NR_ITEM),
    CONSTRAINT FK_ITEM_PEDIDO    FOREIGN KEY (ID_PEDIDO)    REFERENCES PEDIDO (ID_PEDIDO),
    CONSTRAINT FK_ITEM_PRODUTO   FOREIGN KEY (CD_PRODUTO)   REFERENCES PRODUTO (CD_PRODUTO),
    CONSTRAINT FK_ITEM_PRODUTO_2 FOREIGN KEY (CD_PRODUTO_2) REFERENCES PRODUTO (CD_PRODUTO),
    CONSTRAINT CK_ITEM_QUANTIDADE CHECK (QT_ITEM > 0),
    CONSTRAINT CK_ITEM_VALOR CHECK (VL_UNITARIO > 0),
    CONSTRAINT CK_ITEM_NUMERO CHECK (NR_ITEM > 0),
    -- RN13: os dois sabores do meio a meio são diferentes
    CONSTRAINT CK_ITEM_SABORES CHECK (CD_PRODUTO_2 IS NULL OR CD_PRODUTO_2 <> CD_PRODUTO)
) ENGINE = InnoDB;

-- ---------------------------------------------------------------------
-- PAGAMENTO — exatamente um por pedido (RN06)
-- ---------------------------------------------------------------------
CREATE TABLE PAGAMENTO (
    ID_PAGAMENTO         INT           NOT NULL AUTO_INCREMENT,
    ID_PEDIDO            INT           NOT NULL,
    ID_FORMA             INT           NOT NULL,
    VL_TOTAL             DECIMAL(10,2) NOT NULL,                       -- itens + taxa (RN17)
    IN_TROCO_NECESSARIO  BOOLEAN       NULL,                           -- só dinheiro (RN07)
    IN_COMPROVANTE_PIX   BOOLEAN       NULL,                           -- só PIX (RN08)
    CONSTRAINT PK_PAGAMENTO PRIMARY KEY (ID_PAGAMENTO),
    CONSTRAINT UQ_PAGAMENTO_PEDIDO UNIQUE (ID_PEDIDO),                 -- 1:1 com PEDIDO (RN06)
    CONSTRAINT FK_PAGAMENTO_PEDIDO FOREIGN KEY (ID_PEDIDO) REFERENCES PEDIDO (ID_PEDIDO),
    CONSTRAINT FK_PAGAMENTO_FORMA  FOREIGN KEY (ID_FORMA)  REFERENCES FORMAS_PAGAMENTOS (ID_FORMA),
    CONSTRAINT CK_PAGAMENTO_VALOR CHECK (VL_TOTAL > 0)
) ENGINE = InnoDB;
