-- =====================================================================
-- Parâmetros usados nas consultas (alterar aqui para outro período/dia)
-- =====================================================================
SET @INICIO             = '2026-09-22';   -- primeiro dia do período analisado
SET @FIM                = '2026-10-18';   -- último dia do período analisado
SET @DIA_CAIXA          = '2026-10-17';   -- dia do fechamento de caixa (G01)
SET @DT_ULTIMO_REAJUSTE = '2026-10-06';   -- data do último reajuste de preços do cardápio (G08, A06, A07)


-- =====================================================================
-- 5. SELECT com JOIN
-- =====================================================================

-- S01 — Comanda completa do pedido 593: o que a cozinha e o motoboy recebem
-- (pedido + cliente + endereço + itens + produtos + segundo sabor + pagamento)
SELECT p.ID_PEDIDO,
       DATE_FORMAT(p.DT_HORA, '%d/%m/%Y %H:%i')                        AS data_hora,
       p.TP_PEDIDO,
       c.NM_CLIENTE,
       c.DS_TELEFONE,
       CONCAT(e.DS_RUA, ', ', e.NR_RESIDENCIA, ' — ', e.NM_BAIRRO)     AS endereco_entrega,
       i.NR_ITEM,
       i.QT_ITEM,
       i.CD_PRODUTO,
       pr1.NM_SABOR                                                     AS sabor,
       pr2.NM_SABOR                                                     AS segundo_sabor,
       i.DS_OBSERVACAO,
       i.VL_UNITARIO,
       p.VL_TAXA_ENTREGA,
       f.DS_METODO                                                      AS forma_pagamento,
       pg.VL_TOTAL
FROM PEDIDO p
JOIN CLIENTE c                 ON c.ID_CLIENTE   = p.ID_CLIENTE
LEFT JOIN ENDERECO e           ON e.ID_ENDERECO  = p.ID_ENDERECO
JOIN ITEM_PEDIDO i             ON i.ID_PEDIDO    = p.ID_PEDIDO
JOIN PRODUTO pr1               ON pr1.CD_PRODUTO = i.CD_PRODUTO
LEFT JOIN PRODUTO pr2          ON pr2.CD_PRODUTO = i.CD_PRODUTO_2
LEFT JOIN PAGAMENTO pg         ON pg.ID_PEDIDO   = p.ID_PEDIDO
LEFT JOIN FORMAS_PAGAMENTOS f  ON f.ID_FORMA     = pg.ID_FORMA
WHERE p.ID_PEDIDO = 593
ORDER BY i.NR_ITEM;

-- S02 — Atendimento: o atendente digita o telefone e vê o cliente com o endereço ativo (RN09)
SELECT c.ID_CLIENTE,
       c.NM_CLIENTE,
       CONCAT(e.DS_RUA, ', ', e.NR_RESIDENCIA, ' — ', e.NM_BAIRRO)     AS endereco_ativo,
       e.CD_CEP,
       (SELECT COUNT(*) FROM PEDIDO p WHERE p.ID_CLIENTE = c.ID_CLIENTE) AS pedidos_anteriores
FROM CLIENTE c
LEFT JOIN ENDERECO e ON e.ID_CLIENTE = c.ID_CLIENTE AND e.IN_ATIVO = TRUE
WHERE c.DS_TELEFONE = '11962528070';

-- S03 — Histórico de endereços dos clientes que mudaram, com os pedidos enviados a cada um (P1)
SELECT c.ID_CLIENTE,
       c.NM_CLIENTE,
       e.ID_ENDERECO,
       CONCAT(e.DS_RUA, ', ', e.NR_RESIDENCIA, ' — ', e.NM_BAIRRO)     AS endereco,
       IF(e.IN_ATIVO, 'ativo', 'inativo')                               AS situacao,
       DATE_FORMAT(e.DT_CADASTRO, '%d/%m/%Y')                           AS cadastrado_em,
       COUNT(p.ID_PEDIDO)                                               AS pedidos_enviados,
       COALESCE(SUM(p.IN_ENTREGA_FRUSTRADA), 0)                         AS entregas_frustradas
FROM CLIENTE c
JOIN ENDERECO e     ON e.ID_CLIENTE  = c.ID_CLIENTE
LEFT JOIN PEDIDO p  ON p.ID_ENDERECO = e.ID_ENDERECO
WHERE c.ID_CLIENTE IN (SELECT ID_CLIENTE FROM ENDERECO GROUP BY ID_CLIENTE HAVING COUNT(*) > 1)
GROUP BY c.ID_CLIENTE, c.NM_CLIENTE, e.ID_ENDERECO, e.DS_RUA, e.NR_RESIDENCIA, e.NM_BAIRRO, e.IN_ATIVO, e.DT_CADASTRO
ORDER BY c.NM_CLIENTE, e.DT_CADASTRO;

-- S04 — Composição da Mussarela (58) e da Portuguesa (62), com o fornecedor de cada insumo (RF08)
SELECT pr.CD_PRODUTO,
       pr.NM_SABOR,
       i.NM_INSUMO,
       i.TP_INSUMO,
       IF(i.IN_DISPONIVEL, 'sim', 'NÃO')                                AS insumo_disponivel,
       COALESCE(f.NM_FORNECEDOR, 'compra direta pelo dono')             AS fornecedor,
       f.DS_TELEFONE                                                    AS telefone_fornecedor
FROM PRODUTO pr
JOIN PRODUTO_INSUMO pi  ON pi.CD_PRODUTO   = pr.CD_PRODUTO
JOIN INSUMO i           ON i.ID_INSUMO     = pi.ID_INSUMO
LEFT JOIN FORNECEDOR f  ON f.ID_FORNECEDOR = i.ID_FORNECEDOR
WHERE pr.CD_PRODUTO IN (58, 62)
ORDER BY pr.CD_PRODUTO, i.TP_INSUMO, i.NM_INSUMO;


-- =====================================================================
-- 6. UPDATE
-- O MySQL Workbench vem com o "safe update mode" ligado, que recusa UPDATE
-- e DELETE cujo WHERE não use chave. Ele é desligado só durante as seções
-- 6 e 7 e religado no fim.
-- =====================================================================
SET SQL_SAFE_UPDATES = 0;

-- U01 — Entrega frustrada (RN10, P1): o pedido 592 saiu para o endereço antigo do
-- cliente 70; o motoboy não encontrou ninguém, a pizzaria ligou e o cliente informou
-- o endereço novo. Tudo numa transação: ou grava tudo, ou nada (RNF04).
START TRANSACTION;
    UPDATE PEDIDO   SET IN_ENTREGA_FRUSTRADA = TRUE WHERE ID_PEDIDO = 592;   -- registra a ocorrência
    UPDATE ENDERECO SET IN_ATIVO = FALSE           WHERE ID_ENDERECO = 82;   -- endereço antigo vai para o histórico
    INSERT INTO ENDERECO (ID_CLIENTE, DS_RUA, NR_RESIDENCIA, NM_BAIRRO, CD_CEP, IN_ATIVO, DT_CADASTRO)
    VALUES (70, 'Rua das Tulipas', '415', 'Vila Formosa', '03358000', TRUE, '2026-10-18 22:05:00');
    UPDATE PEDIDO   SET DS_STATUS_ENTREGA = 'ENTREGUE' WHERE ID_PEDIDO = 592; -- reentregue no endereço novo
COMMIT;
-- O pedido continua apontando para o endereço para onde foi despachado (82),
-- e é isso que permite contar as entregas frustradas por endereço desatualizado (G06, G07).

-- U02 — Acabou o bacon no meio do expediente (RN04): o insumo fica indisponível
-- e todos os produtos que o usam saem do cardápio
UPDATE INSUMO SET IN_DISPONIVEL = FALSE WHERE NM_INSUMO = 'Bacon';

UPDATE PRODUTO pr
JOIN PRODUTO_INSUMO pi ON pi.CD_PRODUTO = pr.CD_PRODUTO
JOIN INSUMO i          ON i.ID_INSUMO   = pi.ID_INSUMO
SET pr.IN_DISPONIVEL = FALSE
WHERE i.NM_INSUMO = 'Bacon';

-- U03 — Cancelamento do pedido 594 com motivo (RN02, RN05): o pedido não é apagado
UPDATE PEDIDO
SET DS_STATUS_ENTREGA = 'CANCELADO',
    DS_CANCELAMENTO   = 'Cliente desistiu pela demora para ficar pronto'
WHERE ID_PEDIDO = 594;

-- Exemplo do CHECK em ação: cancelar sem motivo é recusado pelo banco.
-- Descomente a linha abaixo e execute para ver o erro 3819 (CK_PEDIDO_CANCELAMENTO):
-- UPDATE PEDIDO SET DS_STATUS_ENTREGA = 'CANCELADO' WHERE ID_PEDIDO = 593;

-- U04 — A cliente 13 trocou de número de telefone (RN09: o telefone continua único)
UPDATE CLIENTE SET DS_TELEFONE = '11987650001' WHERE ID_CLIENTE = 13;


-- =====================================================================
-- 7. DELETE
-- Pedidos nunca são apagados (RN05): cancelamento é um UPDATE (ver U03).
-- As chaves estrangeiras (ON DELETE RESTRICT) impedem apagar cliente,
-- produto ou forma de pagamento que já aparece em pedido.
-- =====================================================================

-- D01 — A receita da pizza de Atum (47) deixou de levar cebola
DELETE FROM PRODUTO_INSUMO
WHERE CD_PRODUTO = 47
  AND ID_INSUMO  = (SELECT ID_INSUMO FROM INSUMO WHERE NM_INSUMO = 'Cebola');

-- D02 — LGPD: a cliente 17, cadastrada sem nenhum pedido nem endereço,
-- pediu a exclusão dos seus dados
DELETE FROM CLIENTE
WHERE ID_CLIENTE = 17
  AND NOT EXISTS (SELECT 1 FROM PEDIDO   p WHERE p.ID_CLIENTE = 17)
  AND NOT EXISTS (SELECT 1 FROM ENDERECO e WHERE e.ID_CLIENTE = 17);

-- Exemplo da FK em ação: um cliente com pedidos não pode ser apagado.
-- Descomente a linha abaixo e execute para ver o erro 1451 (FK_PEDIDO_CLIENTE):
-- DELETE FROM CLIENTE WHERE ID_CLIENTE = 70;

SET SQL_SAFE_UPDATES = 1;


-- =====================================================================
-- 8. CONSULTAS GERENCIAIS
-- Pedidos cancelados não entram em faturamento nem em ticket médio.
-- =====================================================================

-- G01 — Qual foi o fechamento de caixa do dia, por forma de pagamento?
-- Atende: P3 (fechamento de caixa fragmentado), RF04
SELECT IF(GROUPING(f.DS_METODO), 'TOTAL DO DIA', f.DS_METODO)  AS forma_pagamento,
       COUNT(*)                                                 AS pedidos,
       SUM(pg.VL_TOTAL)                                         AS total
FROM PAGAMENTO pg
JOIN PEDIDO p             ON p.ID_PEDIDO = pg.ID_PEDIDO
JOIN FORMAS_PAGAMENTOS f  ON f.ID_FORMA  = pg.ID_FORMA
WHERE DATE(p.DT_HORA) = @DIA_CAIXA
  AND p.DS_STATUS_ENTREGA <> 'CANCELADO'
GROUP BY f.DS_METODO WITH ROLLUP;

-- G02 — Quanto entrou em cada dia do período, por forma de pagamento?
-- Atende: P3; KPI faturamento diário
SELECT DATE_FORMAT(dia, '%d/%m/%Y')                                         AS dia,
       ELT(DAYOFWEEK(dia), 'dom', 'seg', 'ter', 'qua', 'qui', 'sex', 'sáb') AS dia_semana,
       pedidos, dinheiro, pix, cartao, total
FROM (
    SELECT DATE(p.DT_HORA)                                                  AS dia,
           COUNT(*)                                                         AS pedidos,
           SUM(CASE WHEN f.DS_METODO = 'Dinheiro' THEN pg.VL_TOTAL ELSE 0 END) AS dinheiro,
           SUM(CASE WHEN f.DS_METODO = 'PIX'      THEN pg.VL_TOTAL ELSE 0 END) AS pix,
           SUM(CASE WHEN f.DS_METODO = 'Cartão'   THEN pg.VL_TOTAL ELSE 0 END) AS cartao,
           SUM(pg.VL_TOTAL)                                                 AS total
    FROM PAGAMENTO pg
    JOIN PEDIDO p             ON p.ID_PEDIDO = pg.ID_PEDIDO
    JOIN FORMAS_PAGAMENTOS f  ON f.ID_FORMA  = pg.ID_FORMA
    WHERE DATE(p.DT_HORA) BETWEEN @INICIO AND @FIM
      AND p.DS_STATUS_ENTREGA <> 'CANCELADO'
    GROUP BY DATE(p.DT_HORA)
) AS t
ORDER BY t.dia;

-- G03 — Qual o faturamento e o ticket médio de cada semana?
-- Atende: KPI ticket médio semanal (meta proposta: R$ 100,00) e KPI faturamento semanal
SELECT DATE_FORMAT(MIN(DATE(p.DT_HORA)), '%d/%m') AS inicio_semana,
       DATE_FORMAT(MAX(DATE(p.DT_HORA)), '%d/%m') AS fim_semana,
       COUNT(*)                                   AS pedidos_validos,
       SUM(pg.VL_TOTAL)                           AS faturamento,
       ROUND(AVG(pg.VL_TOTAL), 2)                 AS ticket_medio
FROM PEDIDO p
JOIN PAGAMENTO pg ON pg.ID_PEDIDO = p.ID_PEDIDO
WHERE DATE(p.DT_HORA) BETWEEN @INICIO AND @FIM
  AND p.DS_STATUS_ENTREGA <> 'CANCELADO'
GROUP BY YEARWEEK(p.DT_HORA, 3)
ORDER BY MIN(p.DT_HORA);

-- G04 — Qual a taxa de cancelamento de cada semana?
-- Atende: P4 (rastreabilidade de cancelamentos); KPI taxa de cancelamento (meta proposta: abaixo de 3%)
SELECT DATE_FORMAT(MIN(DATE(DT_HORA)), '%d/%m')                            AS inicio_semana,
       COUNT(*)                                                            AS pedidos,
       SUM(DS_STATUS_ENTREGA = 'CANCELADO')                                AS cancelados,
       ROUND(100 * SUM(DS_STATUS_ENTREGA = 'CANCELADO') / COUNT(*), 1)     AS taxa_cancelamento_pct
FROM PEDIDO
WHERE DATE(DT_HORA) BETWEEN @INICIO AND @FIM
GROUP BY YEARWEEK(DT_HORA, 3)
ORDER BY MIN(DT_HORA);

-- G05 — Quais os motivos de cancelamento no período e quanto cada um representa?
-- Atende: P4, RF10
SELECT p.DS_CANCELAMENTO                                         AS motivo,
       COUNT(*)                                                  AS cancelamentos,
       SUM(p.TP_PEDIDO = 'ENTREGA')                              AS de_entrega,
       SUM(p.TP_PEDIDO = 'RETIRADA')                             AS de_retirada,
       ROUND(100 * COUNT(*) / SUM(COUNT(*)) OVER (), 1)          AS pct_dos_cancelamentos,
       COALESCE(SUM(pg.VL_TOTAL), 0)                             AS valor_nao_faturado
FROM PEDIDO p
LEFT JOIN PAGAMENTO pg ON pg.ID_PEDIDO = p.ID_PEDIDO
WHERE p.DS_STATUS_ENTREGA = 'CANCELADO'
  AND DATE(p.DT_HORA) BETWEEN @INICIO AND @FIM
GROUP BY p.DS_CANCELAMENTO
ORDER BY cancelamentos DESC;

-- G06 — Qual a taxa de entregas frustradas por endereço desatualizado em cada semana?
-- Atende: P1 (endereço desatualizado), RF11; KPI taxa de entregas frustradas (meta proposta: abaixo de 1%)
SELECT DATE_FORMAT(MIN(DATE(DT_HORA)), '%d/%m')                                    AS inicio_semana,
       SUM(TP_PEDIDO = 'ENTREGA')                                                  AS entregas,
       SUM(IN_ENTREGA_FRUSTRADA)                                                   AS frustradas,
       ROUND(100 * SUM(IN_ENTREGA_FRUSTRADA) / SUM(TP_PEDIDO = 'ENTREGA'), 1)      AS taxa_frustradas_pct
FROM PEDIDO
WHERE DATE(DT_HORA) BETWEEN @INICIO AND @FIM
GROUP BY YEARWEEK(DT_HORA, 3)
ORDER BY MIN(DT_HORA);

-- G07 — Quais entregas foram frustradas, para onde foram e qual o endereço atual do cliente?
-- Atende: P1
SELECT p.ID_PEDIDO,
       DATE_FORMAT(p.DT_HORA, '%d/%m %H:%i')                              AS data_hora,
       c.NM_CLIENTE,
       c.DS_TELEFONE,
       CONCAT(ea.DS_RUA, ', ', ea.NR_RESIDENCIA, ' — ', ea.NM_BAIRRO)     AS enviado_para,
       CONCAT(en.DS_RUA, ', ', en.NR_RESIDENCIA, ' — ', en.NM_BAIRRO)     AS endereco_atual,
       p.DS_STATUS_ENTREGA                                                AS desfecho
FROM PEDIDO p
JOIN CLIENTE c       ON c.ID_CLIENTE   = p.ID_CLIENTE
JOIN ENDERECO ea     ON ea.ID_ENDERECO = p.ID_ENDERECO
LEFT JOIN ENDERECO en ON en.ID_CLIENTE = p.ID_CLIENTE AND en.IN_ATIVO = TRUE
WHERE p.IN_ENTREGA_FRUSTRADA = TRUE
ORDER BY p.DT_HORA;

-- G08 — Que percentual dos itens lançados desde o último reajuste saiu com preço diferente do cardápio?
-- Atende: P2 (cardápio e pedidos desintegrados), RF12; KPI divergência de preço (meta: 0%)
-- Preço esperado: o do cardápio; no meio a meio, o do sabor mais caro (RN13).
SELECT DATE_FORMAT(MIN(DATE(pe.DT_HORA)), '%d/%m')                     AS inicio_semana,
       COUNT(*)                                                        AS itens_lancados,
       SUM(i.VL_UNITARIO <> GREATEST(p1.VL_PRECO, COALESCE(p2.VL_PRECO, 0)))              AS itens_divergentes,
       ROUND(100 * SUM(i.VL_UNITARIO <> GREATEST(p1.VL_PRECO, COALESCE(p2.VL_PRECO, 0)))
                 / COUNT(*), 2)                                        AS divergencia_pct
FROM ITEM_PEDIDO i
JOIN PEDIDO pe        ON pe.ID_PEDIDO  = i.ID_PEDIDO
JOIN PRODUTO p1       ON p1.CD_PRODUTO = i.CD_PRODUTO
LEFT JOIN PRODUTO p2  ON p2.CD_PRODUTO = i.CD_PRODUTO_2
WHERE DATE(pe.DT_HORA) BETWEEN @DT_ULTIMO_REAJUSTE AND @FIM
GROUP BY YEARWEEK(pe.DT_HORA, 3)
ORDER BY MIN(pe.DT_HORA);

-- G09 — Quais produtos mais vendem e quanto cada um pesa na receita (curva ABC)?
-- Atende: KPI participação na receita por produto (classe A = até 80% da receita acumulada)
-- No meio a meio, cada sabor conta meia pizza e metade do valor.
WITH vendas AS (
    SELECT i.CD_PRODUTO                                                  AS cd,
           i.QT_ITEM * IF(i.CD_PRODUTO_2 IS NULL, 1, 0.5)                AS unidades,
           i.QT_ITEM * i.VL_UNITARIO * IF(i.CD_PRODUTO_2 IS NULL, 1, 0.5) AS receita
    FROM ITEM_PEDIDO i JOIN PEDIDO p ON p.ID_PEDIDO = i.ID_PEDIDO
    WHERE p.DS_STATUS_ENTREGA <> 'CANCELADO' AND DATE(p.DT_HORA) BETWEEN @INICIO AND @FIM
    UNION ALL
    SELECT i.CD_PRODUTO_2, i.QT_ITEM * 0.5, i.QT_ITEM * i.VL_UNITARIO * 0.5
    FROM ITEM_PEDIDO i JOIN PEDIDO p ON p.ID_PEDIDO = i.ID_PEDIDO
    WHERE i.CD_PRODUTO_2 IS NOT NULL
      AND p.DS_STATUS_ENTREGA <> 'CANCELADO' AND DATE(p.DT_HORA) BETWEEN @INICIO AND @FIM
),
por_produto AS (
    SELECT pr.CD_PRODUTO, pr.NM_SABOR, pr.TP_CATEGORIA,
           SUM(v.unidades) AS unidades,
           SUM(v.receita)  AS receita
    FROM vendas v JOIN PRODUTO pr ON pr.CD_PRODUTO = v.cd
    GROUP BY pr.CD_PRODUTO, pr.NM_SABOR, pr.TP_CATEGORIA
)
SELECT CD_PRODUTO, NM_SABOR, TP_CATEGORIA, unidades,
       ROUND(receita, 2)                                                                  AS receita,
       ROUND(100 * receita / SUM(receita) OVER (), 1)                                     AS pct_receita,
       ROUND(100 * SUM(receita) OVER (ORDER BY receita DESC ROWS UNBOUNDED PRECEDING)
                 / SUM(receita) OVER (), 1)                                               AS pct_acumulado,
       CASE WHEN SUM(receita) OVER (ORDER BY receita DESC ROWS UNBOUNDED PRECEDING)
                 <= 0.80 * SUM(receita) OVER () THEN 'A'
            WHEN SUM(receita) OVER (ORDER BY receita DESC ROWS UNBOUNDED PRECEDING)
                 <= 0.95 * SUM(receita) OVER () THEN 'B'
            ELSE 'C' END                                                                  AS classe
FROM por_produto
ORDER BY receita DESC;

-- G10 — Quantos pedidos chegam, em média, em cada hora de cada dia da semana?
-- Atende: KPI pedidos por hora (dimensionamento de atendente e motoboys nos picos)
WITH dias AS (
    SELECT DAYOFWEEK(DT_HORA) AS dw, COUNT(DISTINCT DATE(DT_HORA)) AS n
    FROM PEDIDO WHERE DATE(DT_HORA) BETWEEN @INICIO AND @FIM
    GROUP BY DAYOFWEEK(DT_HORA)
),
ped AS (
    SELECT DAYOFWEEK(DT_HORA) AS dw, HOUR(DT_HORA) AS h
    FROM PEDIDO WHERE DATE(DT_HORA) BETWEEN @INICIO AND @FIM
)
SELECT CONCAT(h, 'h')                                                    AS faixa,
       ROUND(SUM(dw = 3) / (SELECT n FROM dias WHERE dw = 3), 1)         AS terca,
       ROUND(SUM(dw = 4) / (SELECT n FROM dias WHERE dw = 4), 1)         AS quarta,
       ROUND(SUM(dw = 5) / (SELECT n FROM dias WHERE dw = 5), 1)         AS quinta,
       ROUND(SUM(dw = 6) / (SELECT n FROM dias WHERE dw = 6), 1)         AS sexta,
       ROUND(SUM(dw = 7) / (SELECT n FROM dias WHERE dw = 7), 1)         AS sabado,
       ROUND(SUM(dw = 1) / (SELECT n FROM dias WHERE dw = 1), 1)         AS domingo
FROM ped
GROUP BY h
ORDER BY h;

-- G11 — Quais insumos estão em falta, a quem recorrer e quais produtos saíram do cardápio?
-- Atende: P5 (fornecedores sem cadastro), RF08
SELECT i.NM_INSUMO,
       i.TP_INSUMO,
       COALESCE(f.NM_FORNECEDOR, 'compra direta pelo dono')                      AS fornecedor,
       f.DS_TELEFONE                                                             AS telefone,
       CASE WHEN f.ID_FORNECEDOR IS NULL THEN '—'
            WHEN f.IN_ENVIA_MERCADORIA THEN 'fornecedor entrega'
            ELSE 'buscar no fornecedor' END                                      AS reposicao,
       COUNT(pr.CD_PRODUTO)                                                      AS produtos_afetados,
       GROUP_CONCAT(CONCAT(pr.CD_PRODUTO, ' ', pr.NM_SABOR, ' (', LOWER(pr.TP_CATEGORIA), ')')
                    ORDER BY pr.CD_PRODUTO SEPARATOR ', ')                       AS quais_produtos
FROM INSUMO i
LEFT JOIN FORNECEDOR f      ON f.ID_FORNECEDOR = i.ID_FORNECEDOR
LEFT JOIN PRODUTO_INSUMO pi ON pi.ID_INSUMO    = i.ID_INSUMO
LEFT JOIN PRODUTO pr        ON pr.CD_PRODUTO   = pi.CD_PRODUTO
WHERE i.IN_DISPONIVEL = FALSE
GROUP BY i.ID_INSUMO, i.NM_INSUMO, i.TP_INSUMO, f.ID_FORNECEDOR, f.NM_FORNECEDOR, f.DS_TELEFONE, f.IN_ENVIA_MERCADORIA
ORDER BY produtos_afetados DESC;

-- G12 — Que percentual do cardápio está disponível agora, por categoria?
-- Atende: P5; KPI disponibilidade do cardápio (meta proposta: 95% ou mais)
SELECT IF(GROUPING(TP_CATEGORIA), 'CARDÁPIO TODO', TP_CATEGORIA)        AS categoria,
       COUNT(*)                                                         AS produtos,
       SUM(IN_DISPONIVEL)                                               AS disponiveis,
       ROUND(100 * SUM(IN_DISPONIVEL) / COUNT(*), 1)                    AS disponibilidade_pct,
       GROUP_CONCAT(IF(IN_DISPONIVEL, NULL, NM_SABOR) SEPARATOR ', ')   AS indisponiveis
FROM PRODUTO
GROUP BY TP_CATEGORIA WITH ROLLUP;

-- G13 — Quem são os fornecedores, como contatá-los e o que cada um fornece?
-- Atende: P5, RF07
SELECT f.NM_FORNECEDOR,
       f.TP_FORNECIMENTO,
       f.DS_TELEFONE,
       IF(f.IN_ENVIA_MERCADORIA, 'sim', 'não')                          AS envia_mercadoria,
       COUNT(i.ID_INSUMO)                                               AS insumos_fornecidos,
       SUM(i.IN_DISPONIVEL = FALSE)                                     AS em_falta,
       GROUP_CONCAT(i.NM_INSUMO ORDER BY i.NM_INSUMO SEPARATOR ', ')    AS insumos
FROM FORNECEDOR f
LEFT JOIN INSUMO i ON i.ID_FORNECEDOR = f.ID_FORNECEDOR
GROUP BY f.ID_FORNECEDOR, f.NM_FORNECEDOR, f.TP_FORNECIMENTO, f.DS_TELEFONE, f.IN_ENVIA_MERCADORIA
ORDER BY f.NM_FORNECEDOR;

-- G14 — Quanto das entregas é acima de 3 km e quanto a taxa de entrega arrecada por semana?
-- Atende: KPI percentual de entregas com taxa e receita de taxa de entrega (RN12)
SELECT DATE_FORMAT(MIN(DATE(DT_HORA)), '%d/%m')                             AS inicio_semana,
       COUNT(*)                                                             AS entregas,
       SUM(QT_DISTANCIA_KM > 3)                                             AS acima_de_3km,
       ROUND(100 * SUM(QT_DISTANCIA_KM > 3) / COUNT(*), 1)                  AS pct_com_taxa,
       ROUND(AVG(QT_DISTANCIA_KM), 1)                                       AS distancia_media_km,
       SUM(VL_TAXA_ENTREGA)                                                 AS receita_taxa
FROM PEDIDO
WHERE TP_PEDIDO = 'ENTREGA'
  AND DS_STATUS_ENTREGA <> 'CANCELADO'
  AND DATE(DT_HORA) BETWEEN @INICIO AND @FIM
GROUP BY YEARWEEK(DT_HORA, 3)
ORDER BY MIN(DT_HORA);

-- G15 — Com que frequência os clientes compram? Quantos não compraram no período?
-- Atende: KPI taxa de recompra (clientes com 2 ou mais pedidos no período)
SELECT faixa,
       COUNT(*)                                          AS clientes,
       ROUND(100 * COUNT(*) / SUM(COUNT(*)) OVER (), 1)  AS pct_clientes
FROM (
    SELECT c.ID_CLIENTE,
           CASE WHEN COUNT(p.ID_PEDIDO) = 0 THEN '0 — sem compra no período'
                WHEN COUNT(p.ID_PEDIDO) = 1 THEN '1 pedido'
                WHEN COUNT(p.ID_PEDIDO) <= 4 THEN '2 a 4 pedidos'
                ELSE '5 ou mais pedidos' END AS faixa
    FROM CLIENTE c
    LEFT JOIN PEDIDO p ON p.ID_CLIENTE = c.ID_CLIENTE
                      AND p.DS_STATUS_ENTREGA <> 'CANCELADO'
                      AND DATE(p.DT_HORA) BETWEEN @INICIO AND @FIM
    GROUP BY c.ID_CLIENTE
) AS t
GROUP BY faixa
ORDER BY faixa;


-- =====================================================================
-- 9. CONSULTAS DE AUDITORIA
-- Cada consulta lista o que viola a regra; resultado vazio = regra respeitada.
-- As regras garantidas por constraint (RN09, RN12, RN14, RN15, RN16, RN19,
-- RN02 e RN05) não precisam de auditoria: o banco recusa o dado errado.
-- =====================================================================

-- A01 — Existe pedido sem pagamento registrado?
-- Verifica: RN06 (todo pedido tem exatamente um pagamento)
SELECT p.ID_PEDIDO, DATE_FORMAT(p.DT_HORA, '%d/%m %H:%i') AS data_hora, p.TP_PEDIDO, p.DS_STATUS_ENTREGA
FROM PEDIDO p
LEFT JOIN PAGAMENTO pg ON pg.ID_PEDIDO = p.ID_PEDIDO
WHERE pg.ID_PAGAMENTO IS NULL;

-- A02 — Existe pedido sem nenhum item?
-- Verifica: RN06 / RF02 (o pagamento é a soma dos itens; pedido sem item não tem o que cobrar)
SELECT p.ID_PEDIDO, DATE_FORMAT(p.DT_HORA, '%d/%m %H:%i') AS data_hora, p.DS_STATUS_ENTREGA, p.DS_CANCELAMENTO
FROM PEDIDO p
WHERE NOT EXISTS (SELECT 1 FROM ITEM_PEDIDO i WHERE i.ID_PEDIDO = p.ID_PEDIDO);

-- A03 — Existe indicação de troco fora do pagamento em dinheiro, ou dinheiro sem a informação de troco?
-- Verifica: RN07
SELECT pg.ID_PEDIDO, f.DS_METODO, pg.IN_TROCO_NECESSARIO
FROM PAGAMENTO pg
JOIN FORMAS_PAGAMENTOS f ON f.ID_FORMA = pg.ID_FORMA
WHERE (f.DS_METODO <> 'Dinheiro' AND pg.IN_TROCO_NECESSARIO IS NOT NULL)
   OR (f.DS_METODO =  'Dinheiro' AND pg.IN_TROCO_NECESSARIO IS NULL);

-- A04 — Algum pedido pago por PIX foi despachado ou retirado sem comprovante?
-- Verifica: RN08
SELECT p.ID_PEDIDO, DATE_FORMAT(p.DT_HORA, '%d/%m %H:%i') AS data_hora, p.DS_STATUS_ENTREGA, pg.IN_COMPROVANTE_PIX
FROM PEDIDO p
JOIN PAGAMENTO pg         ON pg.ID_PEDIDO = p.ID_PEDIDO
JOIN FORMAS_PAGAMENTOS f  ON f.ID_FORMA   = pg.ID_FORMA
WHERE f.DS_METODO = 'PIX'
  AND p.DS_STATUS_ENTREGA IN ('SAIU PARA ENTREGA', 'ENTREGUE', 'RETIRADO')
  AND COALESCE(pg.IN_COMPROVANTE_PIX, FALSE) = FALSE;

-- A05 — O valor do pagamento bate com a soma dos itens mais a taxa de entrega?
-- Verifica: RN17
SELECT p.ID_PEDIDO,
       pg.VL_TOTAL                                       AS valor_pago,
       SUM(i.QT_ITEM * i.VL_UNITARIO)                    AS soma_itens,
       p.VL_TAXA_ENTREGA                                 AS taxa,
       SUM(i.QT_ITEM * i.VL_UNITARIO) + p.VL_TAXA_ENTREGA AS valor_esperado
FROM PEDIDO p
JOIN PAGAMENTO pg   ON pg.ID_PEDIDO = p.ID_PEDIDO
JOIN ITEM_PEDIDO i  ON i.ID_PEDIDO  = p.ID_PEDIDO
GROUP BY p.ID_PEDIDO, pg.VL_TOTAL, p.VL_TAXA_ENTREGA
HAVING pg.VL_TOTAL <> SUM(i.QT_ITEM * i.VL_UNITARIO) + p.VL_TAXA_ENTREGA;

-- A06 — Alguma pizza meio a meio foi cobrada abaixo do preço do sabor mais caro?
-- Verifica: RN13 (pedidos desde o último reajuste, quando o preço atual do cardápio é a referência)
SELECT i.ID_PEDIDO, i.NR_ITEM,
       p1.NM_SABOR AS sabor_1, p1.VL_PRECO AS preco_1,
       p2.NM_SABOR AS sabor_2, p2.VL_PRECO AS preco_2,
       i.VL_UNITARIO AS cobrado
FROM ITEM_PEDIDO i
JOIN PEDIDO pe   ON pe.ID_PEDIDO  = i.ID_PEDIDO
JOIN PRODUTO p1  ON p1.CD_PRODUTO = i.CD_PRODUTO
JOIN PRODUTO p2  ON p2.CD_PRODUTO = i.CD_PRODUTO_2
WHERE DATE(pe.DT_HORA) >= @DT_ULTIMO_REAJUSTE
  AND i.VL_UNITARIO < GREATEST(p1.VL_PRECO, p2.VL_PRECO);

-- A07 — Algum item foi lançado com preço diferente do cardápio desde o último reajuste?
-- Verifica: RN01 (o produto é lançado pelo código do cardápio, com o preço do cardápio); P2
SELECT i.ID_PEDIDO, DATE_FORMAT(pe.DT_HORA, '%d/%m %H:%i') AS data_hora, i.NR_ITEM,
       p1.CD_PRODUTO, p1.NM_SABOR, p1.VL_PRECO AS preco_cardapio, i.VL_UNITARIO AS preco_lancado
FROM ITEM_PEDIDO i
JOIN PEDIDO pe   ON pe.ID_PEDIDO  = i.ID_PEDIDO
JOIN PRODUTO p1  ON p1.CD_PRODUTO = i.CD_PRODUTO
WHERE i.CD_PRODUTO_2 IS NULL
  AND DATE(pe.DT_HORA) >= @DT_ULTIMO_REAJUSTE
  AND i.VL_UNITARIO <> p1.VL_PRECO;

-- A08 — Existe produto indisponível em pedido ainda em andamento?
-- Verifica: RN18
SELECT p.ID_PEDIDO, p.DS_STATUS_ENTREGA, i.NR_ITEM, pr.CD_PRODUTO, pr.NM_SABOR
FROM PEDIDO p
JOIN ITEM_PEDIDO i ON i.ID_PEDIDO = p.ID_PEDIDO
JOIN PRODUTO pr    ON pr.CD_PRODUTO IN (i.CD_PRODUTO, i.CD_PRODUTO_2)
WHERE p.DS_STATUS_ENTREGA IN ('EM PREPARO', 'SAIU PARA ENTREGA')
  AND pr.IN_DISPONIVEL = FALSE;

-- A09 — Existe produto disponível no cardápio que usa um insumo em falta?
-- Verifica: RN04
SELECT pr.CD_PRODUTO, pr.NM_SABOR, pr.TP_CATEGORIA, i.NM_INSUMO AS insumo_em_falta
FROM PRODUTO pr
JOIN PRODUTO_INSUMO pi ON pi.CD_PRODUTO = pr.CD_PRODUTO
JOIN INSUMO i          ON i.ID_INSUMO   = pi.ID_INSUMO
WHERE pr.IN_DISPONIVEL = TRUE
  AND i.IN_DISPONIVEL  = FALSE;

-- A10 — Algum cliente ficou com mais de um endereço ativo, ou sem endereço ativo depois de uma entrega frustrada?
-- Verifica: RN10 (o endereço novo fica ativo e o anterior vai para o histórico)
SELECT c.ID_CLIENTE, c.NM_CLIENTE,
       SUM(e.IN_ATIVO)                                                                   AS enderecos_ativos,
       (SELECT COUNT(*) FROM PEDIDO p WHERE p.ID_CLIENTE = c.ID_CLIENTE
                                        AND p.IN_ENTREGA_FRUSTRADA = TRUE)               AS entregas_frustradas
FROM CLIENTE c
JOIN ENDERECO e ON e.ID_CLIENTE = c.ID_CLIENTE
GROUP BY c.ID_CLIENTE, c.NM_CLIENTE
HAVING SUM(e.IN_ATIVO) > 1
    OR (SUM(e.IN_ATIVO) = 0 AND entregas_frustradas > 0);
